<script>
(function($,window,document){"use strict";if(!window.AppDataTable||!AppDataTable.ensureAvailable())return;var actions=[],canLineSale=false,timer=null,has=AppDataTable.has,A_CREATE=2,A_UPDATE=3,A_RETURN=32;function esc(v){return String(v==null?"":v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;")}function qty(v){return Number(v||0).toLocaleString("en-IN",{maximumFractionDigits:3})}function st(v){v=Number(v);return v===2?"Loaded":(v===3?"In Route":(v===4?"Returned":(v===5?"Closed":(v===6?"Cancelled":"Draft"))))}
var table=AppDataTable.init("#tripTable",{serverSide:true,searching:true,scrollX:true,autoWidth:false,order:[[1,"desc"]],buttons:[{extend:"copyHtml5",text:"Copy",action:AppDataTable.serverSideExportAction,exportOptions:{columns:[0,1,2,3,4,5,6]}},{extend:"csvHtml5",text:"CSV",action:AppDataTable.serverSideExportAction,exportOptions:{columns:[0,1,2,3,4,5,6]}},{extend:"excelHtml5",text:"Excel",action:AppDataTable.serverSideExportAction,exportOptions:{columns:[0,1,2,3,4,5,6]}},{extend:"pdfHtml5",text:"PDF",orientation:"landscape",pageSize:"A4",action:AppDataTable.serverSideExportAction,exportOptions:{columns:[0,1,2,3,4,5,6]}},{extend:"print",text:"Print",action:AppDataTable.serverSideExportAction,exportOptions:{columns:[0,1,2,3,4,5,6]}}],ajax:function(d,cb){var p=new URLSearchParams();p.set("datatable","1");p.set("draw",d.draw);p.set("start",d.start);p.set("length",d.length);p.set("search[value]",d.search.value||"");if(document.getElementById("statusFilter").value)p.set("status",document.getElementById("statusFilter").value);App.api("api/line-supply.php?"+p.toString()).then(function(r){actions=(r.data.allowed_actions||[]).map(Number);canLineSale=!!r.data.can_line_sale;document.getElementById("addButton").hidden=!has(actions,A_CREATE);AppDataTable.applyExportPermissions(table,actions);cb(r.data.datatable)}).catch(function(e){App.showError(e,"Unable to load Line Supply.");cb({draw:d.draw,recordsTotal:0,recordsFiltered:0,data:[]})})},columns:[{data:"supply_no",render:function(v,t){return t==="display"?esc(v):v}},{data:"supply_date"},{data:"vehicle_no",render:function(v,t){return t==="display"?esc(v):v}},{data:"line_name",render:function(v,t){return t==="display"?esc(v):v}},{data:"loaded_qty",className:"dt-body-right",render:function(v,t){return t==="display"?qty(v):Number(v||0)}},{data:"sold_qty",className:"dt-body-right",render:function(v,t){return t==="display"?qty(v):Number(v||0)}},{data:"status",render:function(v,t){var x=st(v);return t==="display"?'<span class="pill '+(Number(v)===5?'active':(Number(v)===6?'danger':'pending'))+'">'+x+'</span>':x}},{data:null,orderable:false,searchable:false,className:"table-action-icons",render:function(d,t,row){if(t!=="display")return"";var html="",status=Number(row.status);var manageIcon=status===1&&has(actions,A_UPDATE)?"pencil":"eye";var manageLabel=status===1?"Truck Loading":((status===2||status===3)?"Truck Return":((status===4||status===5)?"View Return":"View Trip"));var manageUrl=status===1?row.edit_url:((status===2||status===3||status===4||status===5)?row.return_url:row.edit_url);html+=App.iconActionHtml({href:manageUrl,icon:manageIcon,label:manageLabel});if((status===2||status===3)&&canLineSale)html+=App.iconActionHtml({href:row.sales_url,icon:"receipt-text",label:"Customer Sales"});return html}}],drawCallback:function(){if(window.lucide)lucide.createIcons()}});var c=document.getElementById("tripTable").closest(".table-card"),s=c?c.querySelector(".app-table-search-row"):null;if(s)s.remove();document.getElementById("masterSearch").addEventListener("input",function(){clearTimeout(timer);timer=setTimeout(function(){table.search(document.getElementById("masterSearch").value.trim()).draw()},350)});document.getElementById("statusFilter").addEventListener("change",function(){table.ajax.reload(null,true)});if(window.lucide)lucide.createIcons();})(jQuery,window,document);
